//! What kind of file a path is, as far as a reviewer cares: tests, generated
//! code, and the agent's own labels (matched with [`matches`]).
//!
//! The page matches the agent's patterns itself (`web/src/lib/kinds.ts`), with
//! the same rules; the tests on both sides share their cases.

/// The labels diffd puts on files by itself.
pub const TEST: &str = "test";
pub const GENERATED: &str = "generated";

/// Whether `pattern` (from the agent) names `path`:
///
/// - a path names itself, and a directory everything under it (`web`, `web/`);
/// - `*` is any run of characters but `/`, `**` any run including `/`, `?` one character;
/// - a pattern without a `/` is matched against the file name too (`*.sqlx`, `Cargo.lock`).
pub fn matches(pattern: &str, path: &str) -> bool {
    let pattern = pattern.trim().trim_start_matches("./");
    if pattern.is_empty() {
        return false;
    }
    let dir = pattern.trim_end_matches('/');
    if path == dir || path.strip_prefix(dir).is_some_and(|rest| rest.starts_with('/')) {
        return true;
    }
    if glob(pattern.as_bytes(), path.as_bytes()) {
        return true;
    }
    !pattern.contains('/') && glob(pattern.as_bytes(), path.rsplit('/').next().unwrap_or(path).as_bytes())
}

/// Wildcard matching with backtracking on the last `*` / `**` seen.
fn glob(p: &[u8], s: &[u8]) -> bool {
    // `**/` also matches nothing: `a/**/b` names `a/b`.
    if let Some(i) = p.windows(3).position(|w| w == b"**/") {
        let without = [&p[..i], &p[i + 3..]].concat();
        if glob(&without, s) {
            return true;
        }
    }
    let (mut pi, mut si) = (0, 0);
    // Where to resume after the last star: (pattern index after it, string index, crosses `/`).
    let mut star: Option<(usize, usize, bool)> = None;
    while si < s.len() {
        if pi < p.len() && p[pi] == b'*' {
            let deep = p.get(pi + 1) == Some(&b'*');
            pi += if deep { 2 } else { 1 };
            star = Some((pi, si, deep));
        } else if pi < p.len() && (p[pi] == s[si] || (p[pi] == b'?' && s[si] != b'/')) {
            pi += 1;
            si += 1;
        } else if let Some((after, from, deep)) = star {
            if !deep && s[from] == b'/' {
                return false;
            }
            pi = after;
            si = from + 1;
            star = Some((after, from + 1, deep));
        } else {
            return false;
        }
    }
    p[pi..].iter().all(|&c| c == b'*')
}

/// Whether a path looks like test code.
pub fn is_test(path: &str) -> bool {
    let lower = path.to_ascii_lowercase();
    let name = lower.rsplit('/').next().unwrap_or(&lower);
    let dirs = &lower[..lower.len() - name.len()];
    let in_dir = ["test/", "tests/", "__tests__/", "spec/", "specs/", "e2e/", "testdata/", "fixtures/", "__snapshots__/"]
        .iter()
        .any(|d| dirs.starts_with(d) || dirs.contains(&format!("/{d}")));
    let stem = name.split('.').next().unwrap_or(name);
    in_dir
        || name.contains(".test.")
        || name.contains(".spec.")
        || name.ends_with(".snap")
        || stem.ends_with("_test")
        || stem.ends_with("_spec")
        || stem.starts_with("test_")
        || name == "conftest.py"
        || ((stem.ends_with("test") || stem.ends_with("tests")) && name.ends_with(".java"))
}

/// Why a file is generated, if it is: from its path (lockfiles, `.sqlx`
/// query data, minified bundles, protobuf output) or a marker near its top
/// (`@generated`, `DO NOT EDIT`, `Code generated by …`).
pub fn generated(path: &str, text: Option<&str>) -> Option<&'static str> {
    let name = path.rsplit('/').next().unwrap_or(path);
    const LOCKFILES: &[&str] = &[
        "Cargo.lock",
        "flake.lock",
        "package-lock.json",
        "npm-shrinkwrap.json",
        "yarn.lock",
        "pnpm-lock.yaml",
        "bun.lockb",
        "bun.lock",
        "go.sum",
        "poetry.lock",
        "uv.lock",
        "Pipfile.lock",
        "Gemfile.lock",
        "composer.lock",
        "mix.lock",
        "pubspec.lock",
        "Podfile.lock",
    ];
    if LOCKFILES.contains(&name) || name.ends_with(".lock") {
        return Some("a lockfile");
    }
    if path.starts_with(".sqlx/") || path.contains("/.sqlx/") {
        return Some("generated query data (sqlx)");
    }
    if name.contains(".min.") || name.ends_with(".map") {
        return Some("minified");
    }
    if name.ends_with(".pb.go") || name.ends_with("_pb2.py") || name.ends_with("_pb2.pyi") || name.ends_with(".pb.ts") {
        return Some("generated from protobuf");
    }
    if name.contains(".generated.") || name.contains(".gen.") {
        return Some("generated");
    }
    let head: String = text?.lines().take(8).collect::<Vec<_>>().join("\n");
    let marked = head.contains("@generated")
        || head.contains("DO NOT EDIT")
        || head.contains("Code generated by")
        || head.contains("This file was automatically generated")
        || head.contains("This file is automatically generated")
        || head.contains("Automatically generated by")
        || head.contains("auto-generated");
    marked.then_some("generated")
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The same cases as `web/src/lib/kinds.test.ts`.
    const CASES: &[(&str, &str, bool)] = &[
        ("web", "web/src/a.ts", true),
        ("web/", "web/src/a.ts", true),
        ("web", "webby/a.ts", false),
        ("src/lib.rs", "src/lib.rs", true),
        ("*.sqlx", "crates/x/.sqlx/q.sqlx", true),
        ("*.ts", "web/src/a.ts", true),
        ("web/*.ts", "web/src/a.ts", false),
        ("web/**/*.ts", "web/src/a.ts", true),
        ("web/**/*.ts", "web/a.ts", true),
        ("web/**", "web/src/deep/a.tsx", true),
        ("**/migrations/**", "db/migrations/001.sql", true),
        ("crates/*/src/*.rs", "crates/core/src/lib.rs", true),
        ("crates/*/src/*.rs", "crates/core/src/x/lib.rs", false),
        ("src/?.rs", "src/a.rs", true),
        ("Cargo.lock", "sub/Cargo.lock", true),
        ("", "a", false),
    ];

    #[test]
    fn patterns_match_like_the_page() {
        for &(pattern, path, want) in CASES {
            assert_eq!(matches(pattern, path), want, "{pattern} vs {path}");
        }
    }

    #[test]
    fn tests_are_recognised_by_path() {
        for p in
            ["tests/review_loop.rs", "src/foo_test.go", "web/src/lib.test.ts", "pkg/test_x.py", "a/__tests__/b.tsx", "web/e2e/full.mjs"]
        {
            assert!(is_test(p), "{p}");
        }
        for p in ["src/testing.rs", "src/lib.rs", "contest/a.py", "web/src/latest.ts"] {
            assert!(!is_test(p), "{p}");
        }
    }

    #[test]
    fn generated_files_are_recognised() {
        assert_eq!(generated("Cargo.lock", None), Some("a lockfile"));
        assert_eq!(generated("web/pnpm-lock.yaml", None), Some("a lockfile"));
        assert!(generated("crates/s/.sqlx/query-abc.json", None).is_some());
        assert!(generated("dist/app.min.js", None).is_some());
        assert!(generated("src/gen.rs", Some("// @generated by ts-rs\nexport type A = 1;")).is_some());
        assert!(generated("x.go", Some("// Code generated by protoc-gen-go. DO NOT EDIT.\npackage x")).is_some());
        assert_eq!(generated("src/lib.rs", Some("fn main() {}\n")), None);
        // A marker far down the file is somebody's string, not a header.
        assert_eq!(generated("src/lib.rs", Some(&format!("{}// @generated", "\n".repeat(20)))), None);
    }
}
